    ('0153fb8e-075f-4736-881b-66c8b327e582', 'alice.vojcek@gmail.com', 'Ali', '2026-09-11T19:42:30.95343+00:00', '2026-09-14T21:25:21.435175+00:00', '7e176f07-f981-41fc-9e4b-81c280b36724/avatar-1789421120445.jpg', '2026-09-11', 'Bratislava', 'Bratislavský kraj', 48.1486, 17.1077, true, NULL, NULL, 'Ahoj, som akcna zena s velkou davkou lenivosti :D Rada by som nasla kocku v podobnom veku, ktora ma nenecha sediet na gauci a pojde napr. na bike, lyze, do fitka, ci na prechadzky do prirody s mojimi dvoma jazvecickami. Taku sparing partnerku na zdielanie cesty ODM, sport aj kulturu. Ponukam spolahlivost a uprimnost.', 'sila', NULL, '2026-09-13T19:13:04.984+00:00', 170, NULL, NULL, NULL, NULL, '2026-09-11T19:42:31.023+00:00', 'accepted', NULL, NULL, NULL, NULL, NULL),
