    ('c311ac9f-805d-409d-b239-5d4aba703df0', 'kapustikova.vlasta@gmail.com', 'Vlasta', '2026-09-11T19:42:39.317387+00:00', '2026-09-13T21:20:29.436818+00:00', NULL, '2026-09-11', 'Bratislava', 'Bratislavský kraj', 48.1486, 17.1077, true, 1956, '903903706', 'Budem veľmi rada, keď si ma nájdeš (nájdete),keď sa spriatelime  a budeme spolu zdieľať vytýčený ciel a navzájom sa budeme podporovat....', 'schudnut', 'Pretože sa už v svojom tele dobre necitim a to nehovorím, keď sa postavím pred zrkadlo. Kilá, ktoré som po odchode s pracovného procesu pribrala  mi veľmi prekážajú, cítim sa stále unavená, "neohybna", najvyšší čas začať so sebou niečo robit. Ako sa hovorí, snáď aj z vody priberám....atď...', '2026-09-13T18:33:41.485+00:00', 165, NULL, NULL, 81, 106.2, '2026-09-11T19:42:39.369+00:00', 'accepted', NULL, NULL, NULL, NULL, NULL),
