    ('1ad28372-4cf3-463e-8d2a-f071c06d74bd', 'kubicova.klaudia@gmail.com', 'Klaudia Kubicová', '2026-09-10T17:04:15.355596+00:00', '2026-09-15T07:36:16.518156+00:00', '3ae8c7cd-1ca2-4486-8d6d-9b857afc7b53/avatar-1789330700903.jpg', '2026-09-10', 'Bratislava', 'Bratislava a okolie', 48.1486, 17.1077, true, 1985, '+421911218365', 'Som žena, ktorá miluje pohyb, sebarozvoj a zdravý životný štýl. Rada spoznám ženy, ktoré chcú na sebe pracovať, cítiť sa lepšie a posúvať sa vpred ☺️', 'priateľstvá', 'Vďaka Danielovi a jeho konceptu žijem lepší a kvalitnejší život.Cítim,že v tejto dobe je viac ako potrebné tento trvalo udržateľný životný štýl šíriť ďalej a pomáhať ďalším ženám cítiť sa fit a vo forme.', '2026-09-14T11:34:33.741+00:00', 160, NULL, NULL, NULL, NULL, '2026-09-13T12:03:35.104368+00:00', 'accepted', 'Nekupovala zakladateľské členstvo - rovno sa stala sprievodkyňou.', NULL, 'Klaudia', '84108', 'bratislava-okolie'),
    ('c2a51f8f-c17d-4eb0-9eb7-6e906d875550', 'lenka.kp@gmail.com', 'Lenka Kapustová', '2026-09-10T17:04:41.323309+00:00', '2026-09-13T17:22:13.421233+00:00', NULL, '2026-09-10', NULL, NULL, NULL, NULL, true, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, 'invited', 'Bývalá členka - členstvo končí 23.10.2026.', '2026-10-23', NULL, NULL, NULL),
    ('92d0b354-ba9a-4c52-857d-5157fc7bcd7c', 'lucia.slobodnikova05@gmail.com', 'Lucia Slobodníková', '2026-09-10T17:06:27.106068+00:00', '2026-09-14T16:25:44.083379+00:00', '92d0b354-ba9a-4c52-857d-5157fc7bcd7c/avatar-1789324110956.jpg', '2026-09-10', 'Bratislava - Petržalka', 'Bratislava a okolie', 48.1486, 17.1077, true, 1982, '0911 552 412', 'Ahojky, volajú ma Lucka, Luci. Môj momentálny stav je rozbeh, mala som úraz a už aj ustupujúci problem s kolenom. V klube hľadám parťáčku na spoločné rýchle chôdze, na pokec ohľadne napredovania, možno pochválenia sa a motivovania ako napredujeme spolu. Poprípade Ti môžem pomôcť začať, stanoviť si pravidlá a krok za krokom postupovať k cieľu.', 'vratit_sa', 'Chcem byť silná', '2026-09-14T16:25:43.953+00:00', 166, NULL, NULL, 58, 80, '2026-09-11T19:42:34.351+00:00', 'accepted', NULL, NULL, 'Lucka', '85105', 'bratislava-okolie'),
